insert into public.partner_packages (id, name, text, price_text, items, highlighted, cta, sort_order, is_sample) values ('db806e58-b61b-55f8-8682-f14b8e33e7e3', '{"mk":"Main partner","en":"Main partner"}'::jsonb, '{"mk":"The strongest presence, including our international events.","en":"The strongest presence, including our international events."}'::jsonb, '{"mk":"","en":""}'::jsonb, '[{"id":"package-main-item-1","text":{"mk":"Everything in Gold","en":"Everything in Gold"}},{"id":"package-main-item-2","text":{"mk":"Largest logo, first on the Home page","en":"Largest logo, first on the Home page"}},{"id":"package-main-item-3","text":{"mk":"Branding at our international workshop","en":"Branding at our international workshop"}},{"id":"package-main-item-4","text":{"mk":"Two workshops a year and a company visit","en":"Two workshops a year and a company visit"}},{"id":"package-main-item-5","text":{"mk":"Access to CVs of members who opt in","en":"Access to CVs of members who opt in"}}]'::jsonb, false, '{"mk":"Ask about Main partner","en":"Ask about Main partner"}'::jsonb, 2, true);
insert into public.events (id, slug, title, short_description, scope, type_id, starts_at, ends_at, all_day, location, city, country, organizer, description, agenda, requirements, fee, contact_email, participant_count, country_count, cover_media_id, cover_alt, cover_credit, info_pack_id, video_url, status, publish_at, next_up, applications_enabled, apply_via, external_url, opens_at, deadline, results_on, max_participants, waitlist, admission, seo_title, seo_description, seo_share_media_id, updated_by, created_at, updated_at, is_sample) values ('5e57c2f5-a3b3-531b-8728-eb48165012f2', 'ai-at-the-edge', '{"mk":"Workshop: AI at the Edge","en":"Workshop: AI at the Edge"}'::jsonb, '{"mk":"A week of building and deploying machine-learning models on microcontrollers, in Skopje and Ohrid, for 24 students from across Europe.","en":"A week of building and deploying machine-learning models on microcontrollers, in Skopje and Ohrid, for 24 students from across Europe."}'::jsonb, 'international', '9be1a6f3-d275-5142-8aff-097943648bc5', '2026-11-07T10:00:00+01:00', '2026-11-13T14:00:00+01:00', false, '{"mk":"Skopje & Ohrid, North Macedonia","en":"Skopje & Ohrid, North Macedonia"}'::jsonb, '{"mk":"Skopje & Ohrid","en":"Skopje & Ohrid"}'::jsonb, '{"mk":"North Macedonia","en":"North Macedonia"}'::jsonb, null, '{"mk":"<h3>About the workshop</h3><p>Most AI runs in big data centres. This workshop is about the opposite: <strong>small models that run on a €10 board</strong>, with no internet connection. You will train a model, squeeze it onto a microcontroller and build a working prototype with your team.</p><ul><li><p>Lectures by FEEIT professors and engineers from local companies</p></li><li><p>A full lab day and a company visit</p></li><li><p>A team challenge and a day trip to Ohrid</p></li></ul><p>No prior machine-learning experience is needed. Read the <a href=\"https://eestec.mk/upcoming/ai-at-the-edge\">full programme</a>.</p>","en":"<h3>About the workshop</h3><p>Most AI runs in big data centres. This workshop is about the opposite: <strong>small models that run on a €10 board</strong>, with no internet connection. You will train a model, squeeze it onto a microcontroller and build a working prototype with your team.</p><ul><li><p>Lectures by FEEIT professors and engineers from local companies</p></li><li><p>A full lab day and a company visit</p></li><li><p>A team challenge and a day trip to Ohrid</p></li></ul><p>No prior machine-learning experience is needed. Read the <a href=\"https://eestec.mk/upcoming/ai-at-the-edge\">full programme</a>.</p>"}'::jsonb, '[{"id":"agenda-ai-1","date":"2026-11-07","title":{"mk":"Arrival and welcome party","en":"Arrival and welcome party"},"text":{"mk":"Pick-up from Skopje airport, check-in and a first night in the Old Bazaar.","en":"Pick-up from Skopje airport, check-in and a first night in the Old Bazaar."}},{"id":"agenda-ai-2","date":"2026-11-08","title":{"mk":"Edge AI fundamentals","en":"Edge AI fundamentals"},"text":{"mk":"Lectures at FEEIT: what changes when a model has to fit into 256 KB.","en":"Lectures at FEEIT: what changes when a model has to fit into 256 KB."}},{"id":"agenda-ai-3","date":"2026-11-09","title":{"mk":"Lab: models on microcontrollers","en":"Lab: models on microcontrollers"},"text":{"mk":"Train a keyword-spotting model and deploy it to a dev board.","en":"Train a keyword-spotting model and deploy it to a dev board."}},{"id":"agenda-ai-4","date":"2026-11-10","title":{"mk":"Company visit","en":"Company visit"},"text":{"mk":"See how a local hardware company ships embedded ML in its products.","en":"See how a local hardware company ships embedded ML in its products."}},{"id":"agenda-ai-5","date":"2026-11-11","title":{"mk":"Team challenge","en":"Team challenge"},"text":{"mk":"Build a prototype in teams of four and present it to a jury.","en":"Build a prototype in teams of four and present it to a jury."}},{"id":"agenda-ai-6","date":"2026-11-12","title":{"mk":"Ohrid day trip","en":"Ohrid day trip"},"text":{"mk":"Old town, the lake and the international night.","en":"Old town, the lake and the international night."}},{"id":"agenda-ai-7","date":"2026-11-13","title":{"mk":"Departure","en":"Departure"},"text":{"mk":"Breakfast, goodbyes and transfers to the airport.","en":"Breakfast, goodbyes and transfers to the airport."}}]'::jsonb, '{"mk":"<ul><li><p>Bachelor’s or master’s student in electrical engineering, computer science or a related field</p></li><li><p>Comfortable with basic programming (Python or C)</p></li><li><p>Able to communicate in English</p></li><li><p>EESTEC members get priority; non-members are welcome to apply</p></li></ul>","en":"<ul><li><p>Bachelor’s or master’s student in electrical engineering, computer science or a related field</p></li><li><p>Comfortable with basic programming (Python or C)</p></li><li><p>Able to communicate in English</p></li><li><p>EESTEC members get priority; non-members are welcome to apply</p></li></ul>"}'::jsonb, '{"price":{"mk":"€60","en":"€60"},"note":{"mk":"Covers accommodation, all meals, local transport and the Ohrid trip. Travel to Skopje is not included.","en":"Covers accommodation, all meals, local transport and the Ohrid trip. Travel to Skopje is not included."}}'::jsonb, 'aiedge@eestec.mk', null, null, '02d1752d-3d23-59b7-81fb-e81ae2c30288', 'Two students at a lab bench at FEEIT, connecting a camera module to a small development board.', null, 'e52c4a01-be9d-54b3-b803-dc8b354ef302', '', 'published', null, true, true, 'form', '', '2026-10-01T00:00:00+02:00', '2026-10-18T23:59:00+02:00', '2026-10-25', 24, true, 'selection', '{"mk":""}'::jsonb, '{"mk":""}'::jsonb, null, '6968c77b-9f73-5c37-9d27-2a78798ce64f', '2026-09-14T12:00:00+02:00', '2026-10-04T16:02:00+02:00', true);
