insert into public.events (id, slug, title, short_description, scope, type_id, starts_at, ends_at, all_day, location, city, country, organizer, description, agenda, requirements, fee, contact_email, participant_count, country_count, cover_media_id, cover_alt, cover_credit, info_pack_id, video_url, status, publish_at, next_up, applications_enabled, apply_via, external_url, opens_at, deadline, results_on, max_participants, waitlist, admission, seo_title, seo_description, seo_share_media_id, updated_by, created_at, updated_at, is_sample) values ('4c9b724d-d545-5920-9f8c-1ea5877b2954', 'power-up-2026', '{"mk":"Workshop: Power Up — Renewable Grids","en":"Workshop: Power Up — Renewable Grids"}'::jsonb, '{"mk":"Seven days in Skopje and Ohrid about how power grids change when most of the energy comes from the sun and the wind.","en":"Seven days in Skopje and Ohrid about how power grids change when most of the energy comes from the sun and the wind."}'::jsonb, 'international', '9be1a6f3-d275-5142-8aff-097943648bc5', '2026-05-18T00:00:00+02:00', '2026-05-24T23:59:00+02:00', true, '{"mk":"Skopje & Ohrid, North Macedonia","en":"Skopje & Ohrid, North Macedonia"}'::jsonb, '{"mk":"Skopje & Ohrid","en":"Skopje & Ohrid"}'::jsonb, '{"mk":"North Macedonia","en":"North Macedonia"}'::jsonb, null, '{"mk":"<h3>About the workshop</h3><p>Power Up brought 24 students from 14 countries to Skopje for a week of lectures, lab work and field visits. Professors from FEEIT explained how a national grid balances supply and demand, and engineers from local energy companies showed what that looks like in practice.</p><h3>What we did</h3><ul><li><p>A full lab day in the FEEIT high-voltage laboratory</p></li><li><p>A visit to a 10 MW solar plant outside Skopje</p></li><li><p>A team challenge: keep a simulated grid stable through a cloudy afternoon</p></li><li><p>An international night and a weekend in Ohrid</p></li></ul><p>The workshop was organized by a team of 16 LC Skopje members. Most of them were organizing an international event for the first time.</p>","en":"<h3>About the workshop</h3><p>Power Up brought 24 students from 14 countries to Skopje for a week of lectures, lab work and field visits. Professors from FEEIT explained how a national grid balances supply and demand, and engineers from local energy companies showed what that looks like in practice.</p><h3>What we did</h3><ul><li><p>A full lab day in the FEEIT high-voltage laboratory</p></li><li><p>A visit to a 10 MW solar plant outside Skopje</p></li><li><p>A team challenge: keep a simulated grid stable through a cloudy afternoon</p></li><li><p>An international night and a weekend in Ohrid</p></li></ul><p>The workshop was organized by a team of 16 LC Skopje members. Most of them were organizing an international event for the first time.</p>"}'::jsonb, '[]'::jsonb, '{"mk":""}'::jsonb, '{"price":{"mk":""},"note":{"mk":""}}'::jsonb, '', 24, 14, 'e93bd676-1171-583a-ac0c-0eb5f901259e', 'All 24 participants in front of FEEIT on day one', null, null, '', 'published', null, false, false, 'form', '', null, null, null, 24, true, 'selection', '{"mk":""}'::jsonb, '{"mk":""}'::jsonb, null, '6968c77b-9f73-5c37-9d27-2a78798ce64f', '2026-06-01T10:30:00+02:00', '2026-06-01T10:30:00+02:00', true);
