insert into public.events (id, slug, title, short_description, scope, type_id, starts_at, ends_at, all_day, location, city, country, organizer, description, agenda, requirements, fee, contact_email, participant_count, country_count, cover_media_id, cover_alt, cover_credit, info_pack_id, video_url, status, publish_at, next_up, applications_enabled, apply_via, external_url, opens_at, deadline, results_on, max_participants, waitlist, admission, seo_title, seo_description, seo_share_media_id, updated_by, created_at, updated_at, is_sample) values ('75af08d9-b5c7-501e-8489-d4fc3f4804a1', 'power-grid-lecture', '{"mk":"Lecture evening: How the Macedonian power grid keeps the lights on","en":"Lecture evening: How the Macedonian power grid keeps the lights on"}'::jsonb, '{"mk":"An evening lecture for FEEIT students about how the national grid balances supply and demand every second.","en":"An evening lecture for FEEIT students about how the national grid balances supply and demand every second."}'::jsonb, 'local', '8f0ca3af-b083-5437-a822-2c94067dcfc4', '2024-12-09T18:00:00+01:00', '2024-12-09T18:00:00+01:00', false, '{"mk":"Amphitheatre 1, FEEIT, Skopje","en":"Amphitheatre 1, FEEIT, Skopje"}'::jsonb, '{"mk":""}'::jsonb, '{"mk":""}'::jsonb, 'FEEIT Student Parliament, with LC Skopje', '{"mk":"<h3>About the lecture</h3><p>Every second, the power grid has to produce exactly as much electricity as the country uses. In this evening lecture, an engineer from the national transmission operator explained how that balance is kept, what happens when a power plant suddenly trips, and why more solar power makes the job harder.</p><p>The lecture was open to all FEEIT students and was followed by questions and a short tour of the faculty&#39;s power systems lab.</p>","en":"<h3>About the lecture</h3><p>Every second, the power grid has to produce exactly as much electricity as the country uses. In this evening lecture, an engineer from the national transmission operator explained how that balance is kept, what happens when a power plant suddenly trips, and why more solar power makes the job harder.</p><p>The lecture was open to all FEEIT students and was followed by questions and a short tour of the faculty&#39;s power systems lab.</p>"}'::jsonb, '[]'::jsonb, '{"mk":""}'::jsonb, '{"price":{"mk":""},"note":{"mk":""}}'::jsonb, '', null, null, 'b6939dac-0027-54b4-8fc0-78925feef20d', 'A lecture hall at FEEIT', null, null, '', 'published', null, false, false, 'form', '', null, null, null, 24, true, 'selection', '{"mk":""}'::jsonb, '{"mk":""}'::jsonb, null, '92415856-7264-5467-a08a-438e8b79ad21', '2024-12-09T18:00:00+01:00', '2024-12-09T18:00:00+01:00', true);
