insert into public.page_content (page, content, is_sample) values ('home', '{"hero":{"eyebrow":{"mk":"EESTEC LC Skopje · FEEIT, Ss. Cyril and Methodius University","en":"EESTEC LC Skopje · FEEIT, Ss. Cyril and Methodius University"},"headline":{"mk":"Learn more. Travel further. Build it together.","en":"Learn more. Travel further. Build it together."},"subtitle":{"mk":"Connecting electrical engineering and computer science students across Europe through workshops, exchanges and trainings.","en":"Connecting electrical engineering and computer science students across Europe through workshops, exchanges and trainings."},"primary":{"label":{"mk":"Join Us","en":"Join Us"},"href":"/join"},"secondary":{"label":{"mk":"Upcoming Events","en":"Upcoming Events"},"href":"/upcoming"},"image":null},"about":{"body":{"mk":"EESTEC, the Electrical Engineering STudents'' European assoCiation, is a non-profit, non-political student association founded in 1986 in the Netherlands.\n\nToday it is a network of Local Committees at technical universities across Europe. Together they organize workshops, exchanges and trainings that help students grow professionally and personally — and make friends in every corner of the continent.","en":"EESTEC, the Electrical Engineering STudents'' European assoCiation, is a non-profit, non-political student association founded in 1986 in the Netherlands.\n\nToday it is a network of Local Committees at technical universities across Europe. Together they organize workshops, exchanges and trainings that help students grow professionally and personally — and make friends in every corner of the continent."}},"activities":[{"id":"act-workshops","icon":"cpu","title":{"mk":"Workshops","en":"Workshops"},"text":{"mk":"A week of lectures, labs and city life on a technical topic, hosted by one committee for students from all over Europe.","en":"A week of lectures, labs and city life on a technical topic, hosted by one committee for students from all over Europe."}},{"id":"act-exchanges","icon":"exchange","title":{"mk":"Exchanges","en":"Exchanges"},"text":{"mk":"Short, culture-first trips to another committee''s city. The easiest way to go international for the first time.","en":"Short, culture-first trips to another committee''s city. The easiest way to go international for the first time."}},{"id":"act-weekends","icon":"zap","title":{"mk":"Motivational Weekends","en":"Motivational Weekends"},"text":{"mk":"Weekend trainings that turn new members into confident organizers and team players.","en":"Weekend trainings that turn new members into confident organizers and team players."}},{"id":"act-soft-skills","icon":"message","title":{"mk":"Soft Skills trainings","en":"Soft Skills trainings"},"text":{"mk":"Communication, leadership and teamwork sessions led by EESTEC''s own certified trainers.","en":"Communication, leadership and teamwork sessions led by EESTEC''s own certified trainers."}},{"id":"act-competitions","icon":"trophy","title":{"mk":"Competitions","en":"Competitions"},"text":{"mk":"Team challenges like the EESTech Challenge and RoboMac: local rounds first, international finals next.","en":"Team challenges like the EESTech Challenge and RoboMac: local rounds first, international finals next."}},{"id":"act-congress","icon":"users","title":{"mk":"Congress","en":"Congress"},"text":{"mk":"The yearly gathering where delegates from every committee shape the future of the association.","en":"The yearly gathering where delegates from every committee shape the future of the association."}}],"milestones":[{"id":"ms-2005","year":2005,"title":{"mk":"International networking workshop","en":"International networking workshop"},"text":{"mk":"A week of networking in Skopje for students from across Europe, closing with a weekend in Ohrid.","en":"A week of networking in Skopje for students from across Europe, closing with a weekend in Ohrid."},"photo":{"mediaId":"b881d8cd-e734-5af4-a7dd-c26dd6cd008c","alt":{"mk":"Workshop participants on the shore of Lake Ohrid","en":"Workshop participants on the shore of Lake Ohrid"}}},{"id":"ms-2011","year":2011,"title":{"mk":"Hosting the EESTEC Chairpersons’ Meeting","en":"Hosting the EESTEC Chairpersons’ Meeting"},"text":{"mk":"LC Skopje welcomed the chairpersons of committees from all over Europe for the ECM.","en":"LC Skopje welcomed the chairpersons of committees from all over Europe for the ECM."},"photo":null},{"id":"ms-2015","year":2015,"title":{"mk":"RoboMac is born","en":"RoboMac is born"},"text":{"mk":"A robotics competition co-organized with IEEE SB Skopje and the FEEIT Student Parliament.","en":"A robotics competition co-organized with IEEE SB Skopje and the FEEIT Student Parliament."},"photo":{"mediaId":"e2a8453c-1594-5a67-af37-b6c698ccef0c","alt":{"mk":"Small robots on the RoboMac arena","en":"Small robots on the RoboMac arena"}}},{"id":"ms-2019","year":2019,"title":{"mk":"Soft Skills Academy","en":"Soft Skills Academy"},"text":{"mk":"Our first local training academy, run by EESTEC trainers for FEEIT students.","en":"Our first local training academy, run by EESTEC trainers for FEEIT students."},"photo":null},{"id":"ms-2025","year":2025,"title":{"mk":"20 years of international events","en":"20 years of international events"},"text":{"mk":"Two decades of workshops and exchanges hosted in Skopje and Ohrid.","en":"Two decades of workshops and exchanges hosted in Skopje and Ohrid."},"photo":{"mediaId":"4a5a061e-833b-57bc-9830-f6f6f3fe9418","alt":{"mk":"Anniversary group photo in front of FEEIT","en":"Anniversary group photo in front of FEEIT"}}}],"stats":[{"id":"st-committees","label":{"mk":"Local Committees","en":"Local Committees"},"value":35,"suffix":""},{"id":"st-countries","label":{"mk":"Countries","en":"Countries"},"value":21,"suffix":""},{"id":"st-members","label":{"mk":"EESTEC members in Europe","en":"EESTEC members in Europe"},"value":5000,"suffix":"+"},{"id":"st-skopje-members","label":{"mk":"LC Skopje members","en":"LC Skopje members"},"value":80,"suffix":""},{"id":"st-events","label":{"mk":"Events by LC Skopje","en":"Events by LC Skopje"},"value":150,"suffix":"+"}],"layout":[{"key":"about","visible":true},{"key":"tradition","visible":true},{"key":"numbers","visible":true},{"key":"map","visible":true},{"key":"meeting","visible":true},{"key":"latest","visible":true},{"key":"journey","visible":true}]}'::jsonb, true);
insert into public.page_content (page, content, is_sample) values ('journey', '{"hero":{"eyebrow":{"mk":"EESTEC Journey","en":"EESTEC Journey"},"title":{"mk":"From your first meeting to alumni","en":"From your first meeting to alumni"},"lead":{"mk":"Six steps to get the most out of EESTEC. Start wherever you are.","en":"Six steps to get the most out of EESTEC. Start wherever you are."}},"steps":[{"id":"step-1","icon":"user-plus","title":{"mk":"Join","en":"Join"},"text":{"mk":"Become a member of LC Skopje.","en":"Become a member of LC Skopje."},"button":{"label":{"mk":"Join Us","en":"Join Us"},"href":"/join"},"bullets":[{"id":"step-1-b1","text":{"mk":"Meet students from every year and department","en":"Meet students from every year and department"}},{"id":"step-1-b2","text":{"mk":"Come to the weekly meeting every Wednesday","en":"Come to the weekly meeting every Wednesday"}},{"id":"step-1-b3","text":{"mk":"No experience needed, just curiosity","en":"No experience needed, just curiosity"}}],"photo":{"mediaId":"3eed72c7-ae14-5987-bbdb-4085079f9930","alt":{"mk":"Students sitting around a table at a Wednesday meeting in room 117","en":"Students sitting around a table at a Wednesday meeting in room 117"}},"quote":{"text":{"mk":"I came to one meeting for the free pizza. Three years later I’m still here.","en":"I came to one meeting for the free pizza. Three years later I’m still here."},"author":{"mk":"Elena Petrovska · member since 2023","en":"Elena Petrovska · member since 2023"}}},{"id":"step-2","icon":"calendar","title":{"mk":"Participate","en":"Participate"},"text":{"mk":"Attend local workshops, trainings and socials.","en":"Attend local workshops, trainings and socials."},"button":{"label":{"mk":"Upcoming Events","en":"Upcoming Events"},"href":"/upcoming"},"bullets":[{"id":"step-2-b1","text":{"mk":"Hands-on technical workshops at FEEIT","en":"Hands-on technical workshops at FEEIT"}},{"id":"step-2-b2","text":{"mk":"Soft skills trainings with certified trainers","en":"Soft skills trainings with certified trainers"}},{"id":"step-2-b3","text":{"mk":"Socials, trips and the New Year party","en":"Socials, trips and the New Year party"}}],"photo":{"mediaId":"f2297300-f42d-5cd3-b0e8-e035eba9f768","alt":{"mk":"Students soldering at a local workshop","en":"Students soldering at a local workshop"}},"quote":{"text":{"mk":"The PCB workshop taught me more than a whole semester of theory.","en":"The PCB workshop taught me more than a whole semester of theory."},"author":{"mk":"Daniel Ristov · 2nd year, FEEIT","en":"Daniel Ristov · 2nd year, FEEIT"}}},{"id":"step-3","icon":"heart","title":{"mk":"Volunteer & Organize","en":"Volunteer & Organize"},"text":{"mk":"Join a team and help organize events.","en":"Join a team and help organize events."},"button":{"label":{"mk":"Meet the teams","en":"Meet the teams"},"href":"/members#teams"},"bullets":[{"id":"step-3-b1","text":{"mk":"Teams for IT, PR, HR, fundraising and events","en":"Teams for IT, PR, HR, fundraising and events"}},{"id":"step-3-b2","text":{"mk":"Learn project management by doing","en":"Learn project management by doing"}},{"id":"step-3-b3","text":{"mk":"Organize your first event with a mentor","en":"Organize your first event with a mentor"}}],"photo":{"mediaId":"b531bd92-2362-5544-b606-8f03f4a8ee6a","alt":{"mk":"An organizing team planning an event at a whiteboard","en":"An organizing team planning an event at a whiteboard"}},"quote":{"text":{"mk":"Organizing a workshop for 24 people is the best crash course in teamwork.","en":"Organizing a workshop for 24 people is the best crash course in teamwork."},"author":{"mk":"Marija Stojanovska · Power Up organizer","en":"Marija Stojanovska · Power Up organizer"}}},{"id":"step-4","icon":"globe","title":{"mk":"Go International","en":"Go International"},"text":{"mk":"Apply for workshops and exchanges across Europe.","en":"Apply for workshops and exchanges across Europe."},"button":{"label":{"mk":"See events abroad","en":"See events abroad"},"href":"/upcoming?scope=international"},"bullets":[{"id":"step-4-b1","text":{"mk":"Workshops and exchanges in 20+ countries","en":"Workshops and exchanges in 20+ countries"}},{"id":"step-4-b2","text":{"mk":"Usually only a small participation fee","en":"Usually only a small participation fee"}},{"id":"step-4-b3","text":{"mk":"Friends in every corner of Europe","en":"Friends in every corner of Europe"}}],"photo":{"mediaId":"3da30479-1fd9-56af-bf54-5d13e5e3e38f","alt":{"mk":"An exchange group posing in front of TU Delft","en":"An exchange group posing in front of TU Delft"}},"quote":{"text":{"mk":"My first exchange changed everything.","en":"My first exchange changed everything."},"author":{"mk":"Stefan Nikolovski · exchange in Delft, 2026","en":"Stefan Nikolovski · exchange in Delft, 2026"}}},{"id":"step-5","icon":"flag","title":{"mk":"Lead","en":"Lead"},"text":{"mk":"Become a coordinator, board member or join international teams, ECM and Congress.","en":"Become a coordinator, board member or join international teams, ECM and Congress."},"button":{"label":{"mk":"How to get involved","en":"How to get involved"},"href":"/join"},"bullets":[{"id":"step-5-b1","text":{"mk":"Coordinate a team or a project","en":"Coordinate a team or a project"}},{"id":"step-5-b2","text":{"mk":"Run for the LC Skopje board","en":"Run for the LC Skopje board"}},{"id":"step-5-b3","text":{"mk":"Represent Skopje at ECM and Congress","en":"Represent Skopje at ECM and Congress"}}],"photo":{"mediaId":"074231c6-033f-59b5-9dcf-92eec53bfad0","alt":{"mk":"The LC Skopje delegation at an EESTEC Congress","en":"The LC Skopje delegation at an EESTEC Congress"}},"quote":{"text":{"mk":"Leading the board taught me to make decisions with 80 people watching.","en":"Leading the board taught me to make decisions with 80 people watching."},"author":{"mk":"Ana Trajkovska · chairperson 2025","en":"Ana Trajkovska · chairperson 2025"}}},{"id":"step-6","icon":"link","title":{"mk":"Stay Connected","en":"Stay Connected"},"text":{"mk":"Become alumni and support the next generation.","en":"Become alumni and support the next generation."},"button":{"label":{"mk":"Our alumni","en":"Our alumni"},"href":"/members?group=alumni"},"bullets":[{"id":"step-6-b1","text":{"mk":"Mentor new members","en":"Mentor new members"}},{"id":"step-6-b2","text":{"mk":"Give a talk or bring your company to FEEIT","en":"Give a talk or bring your company to FEEIT"}},{"id":"step-6-b3","text":{"mk":"Stay part of the network for life","en":"Stay part of the network for life"}}],"photo":{"mediaId":"860816ea-7402-594e-a222-d8c866eab271","alt":{"mk":"An alumnus giving a talk at the career day","en":"An alumnus giving a talk at the career day"}},"quote":{"text":{"mk":"Half of my colleagues today are people I met through EESTEC.","en":"Half of my colleagues today are people I met through EESTEC."},"author":{"mk":"Nikola Georgiev · alumnus, 2019","en":"Nikola Georgiev · alumnus, 2019"}}}],"cta":{"title":{"mk":"Ready for step one?","en":"Ready for step one?"},"text":{"mk":"It takes five minutes: tell us a bit about yourself, then come to a Wednesday meeting.","en":"It takes five minutes: tell us a bit about yourself, then come to a Wednesday meeting."},"button":{"label":{"mk":"Start your journey","en":"Start your journey"},"href":"/join"}}}'::jsonb, true);
insert into public.page_content (page, content, is_sample) values ('join', '{"hero":{"eyebrow":{"mk":"Join Us","en":"Join Us"},"title":{"mk":"Become an EESTECer","en":"Become an EESTECer"},"lead":{"mk":"Learn, travel and organize with 80 engineering students in Skopje and 5,000+ across Europe.","en":"Learn, travel and organize with 80 engineering students in Skopje and 5,000+ across Europe."}},"headings":{"why":{"mk":"What you get out of it","en":"What you get out of it"},"who":{"mk":"Students in Skopje, any year","en":"Students in Skopje, any year"},"how":{"mk":"Four steps to full membership","en":"Four steps to full membership"},"rules":{"mk":"The short version","en":"The short version"},"faq":{"mk":"Questions we hear a lot","en":"Questions we hear a lot"},"apply":{"mk":"Apply for membership","en":"Apply for membership"}},"glance":[{"id":"glance-1","icon":"users","label":{"mk":"Who","en":"Who"},"value":{"mk":"University students in Skopje","en":"University students in Skopje"}},{"id":"glance-2","icon":"clock","label":{"mk":"Time","en":"Time"},"value":{"mk":"About 2–4 hours a week","en":"About 2–4 hours a week"}},{"id":"glance-3","icon":"wallet","label":{"mk":"Fee","en":"Fee"},"value":{"mk":"600 MKD / year, once you’re a full member","en":"600 MKD / year, once you’re a full member"}}],"benefits":[{"id":"benefit-1","icon":"globe","title":{"mk":"International experience","en":"International experience"},"text":{"mk":"Workshops and exchanges in 20+ countries, often for a small fee.","en":"Workshops and exchanges in 20+ countries, often for a small fee."}},{"id":"benefit-2","icon":"chip","title":{"mk":"Technical knowledge","en":"Technical knowledge"},"text":{"mk":"Hands-on workshops on embedded systems, AI, power and more.","en":"Hands-on workshops on embedded systems, AI, power and more."}},{"id":"benefit-3","icon":"chat","title":{"mk":"Soft skills","en":"Soft skills"},"text":{"mk":"Communication, leadership and teamwork trainings with certified trainers.","en":"Communication, leadership and teamwork trainings with certified trainers."}},{"id":"benefit-4","icon":"users","title":{"mk":"Friends across Europe","en":"Friends across Europe"},"text":{"mk":"A network of 5,000+ students who will happily host you.","en":"A network of 5,000+ students who will happily host you."}},{"id":"benefit-5","icon":"clip","title":{"mk":"Organizing experience","en":"Organizing experience"},"text":{"mk":"Plan real events with real budgets, from a lecture to a week-long workshop.","en":"Plan real events with real budgets, from a lecture to a week-long workshop."}},{"id":"benefit-6","icon":"briefcase","title":{"mk":"Contacts with companies","en":"Contacts with companies"},"text":{"mk":"Meet partners at career days, company visits and workshops.","en":"Meet partners at career days, company visits and workshops."}}],"eligibility":{"items":[{"id":"elig-1","text":{"mk":"Bachelor’s, master’s or PhD students at FEEIT","en":"Bachelor’s, master’s or PhD students at FEEIT"}},{"id":"elig-2","text":{"mk":"Students from other faculties and universities in Skopje are welcome too","en":"Students from other faculties and universities in Skopje are welcome too"}},{"id":"elig-3","text":{"mk":"Any year of study, including your final year","en":"Any year of study, including your final year"}},{"id":"elig-4","text":{"mk":"No experience needed, just curiosity and some free time","en":"No experience needed, just curiosity and some free time"}}],"noteTitle":{"mk":"Not sure you qualify?","en":"Not sure you qualify?"},"noteText":{"mk":"The exact rules are set by the board. Write to us or just come to a Wednesday meeting and ask.","en":"The exact rules are set by the board. Write to us or just come to a Wednesday meeting and ask."}},"steps":[{"id":"step-1","title":{"mk":"Fill in the form","en":"Fill in the form"},"text":{"mk":"Five minutes, right here on this page.","en":"Five minutes, right here on this page."}},{"id":"step-2","title":{"mk":"Come to a weekly meeting","en":"Come to a weekly meeting"},"text":{"mk":"Wednesdays at 18:00 in room 117, or the next info session.","en":"Wednesdays at 18:00 in room 117, or the next info session."}},{"id":"step-3","title":{"mk":"Join a team","en":"Join a team"},"text":{"mk":"IT, PR, design, events, fundraising or trainings.","en":"IT, PR, design, events, fundraising or trainings."}},{"id":"step-4","title":{"mk":"Become a full member","en":"Become a full member"},"text":{"mk":"After 3 months of activity and paying the yearly fee.","en":"After 3 months of activity and paying the yearly fee."}}],"fee":{"amount":{"mk":"600 MKD","en":"600 MKD"},"per":{"mk":"/ academic year","en":"/ academic year"},"note":{"mk":"You only pay when you become a full member. Pay in cash at a weekly meeting or by bank transfer; the details are in your welcome e-mail.","en":"You only pay when you become a full member. Pay in cash at a weekly meeting or by bank transfer; the details are in your welcome e-mail."}},"rules":{"intro":{"mk":"The official documents are at the bottom of this section. Here is what they mean in practice.","en":"The official documents are at the bottom of this section. Here is what they mean in practice."},"rights":[{"id":"right-1","text":{"mk":"Take part in all local and international events","en":"Take part in all local and international events"}},{"id":"right-2","text":{"mk":"Vote and run for the LC Skopje board","en":"Vote and run for the LC Skopje board"}},{"id":"right-3","text":{"mk":"Use the EESTEC network for your own projects","en":"Use the EESTEC network for your own projects"}},{"id":"right-4","text":{"mk":"Get support and mentoring from older members","en":"Get support and mentoring from older members"}}],"duties":[{"id":"duty-1","text":{"mk":"Be active in at least one team","en":"Be active in at least one team"}},{"id":"duty-2","text":{"mk":"Come to the weekly meetings when you can","en":"Come to the weekly meetings when you can"}},{"id":"duty-3","text":{"mk":"Pay the yearly membership fee","en":"Pay the yearly membership fee"}},{"id":"duty-4","text":{"mk":"Follow the statute and the code of conduct","en":"Follow the statute and the code of conduct"}}],"conduct":[{"id":"conduct-1","icon":"heart","title":{"mk":"Respect","en":"Respect"},"text":{"mk":"Treat everyone with respect, online and offline.","en":"Treat everyone with respect, online and offline."}},{"id":"conduct-2","icon":"users","title":{"mk":"Inclusion","en":"Inclusion"},"text":{"mk":"Everyone is welcome, whatever their background or beliefs.","en":"Everyone is welcome, whatever their background or beliefs."}},{"id":"conduct-3","icon":"flag","title":{"mk":"Represent us well","en":"Represent us well"},"text":{"mk":"At events abroad you represent LC Skopje and EESTEC.","en":"At events abroad you represent LC Skopje and EESTEC."}},{"id":"conduct-4","icon":"shield","title":{"mk":"Zero tolerance","en":"Zero tolerance"},"text":{"mk":"Harassment and discrimination lead to removal. Report it to the board in confidence.","en":"Harassment and discrimination lead to removal. Report it to the board in confidence."}}],"international":{"before":[{"id":"before-1","text":{"mk":"Write your own motivation letter; the board can review it","en":"Write your own motivation letter; the board can review it"}},{"id":"before-2","text":{"mk":"Apply only if you can really attend","en":"Apply only if you can really attend"}}],"during":[{"id":"during-1","text":{"mk":"Attend all sessions","en":"Attend all sessions"}},{"id":"during-2","text":{"mk":"Follow the host committee’s rules","en":"Follow the host committee’s rules"}}],"after":[{"id":"after-1","text":{"mk":"Within 2 weeks, write a short report or a Memories post","en":"Within 2 weeks, write a short report or a Memories post"}},{"id":"after-2","text":{"mk":"Share what you learned at a weekly meeting","en":"Share what you learned at a weekly meeting"}}]}},"documents":[{"id":"doc-1","title":{"mk":"Statute","en":"Statute"},"mediaId":"215bd75f-c0e6-506a-b159-5e278c0f0970"},{"id":"doc-2","title":{"mk":"Internal rules","en":"Internal rules"},"mediaId":"16932eac-86eb-5067-9e85-35c1b28e0f0e"},{"id":"doc-3","title":{"mk":"Code of conduct","en":"Code of conduct"},"mediaId":"977f4dc1-9c5e-59c1-b68c-90a937dbf95c"}],"faq":[{"id":"faq-1","question":{"mk":"Do I have to study at FEEIT?","en":"Do I have to study at FEEIT?"},"answer":{"mk":"No. Most members study at FEEIT, but students from other faculties and universities in Skopje are welcome too.","en":"No. Most members study at FEEIT, but students from other faculties and universities in Skopje are welcome too."}},{"id":"faq-2","question":{"mk":"How much time does it take?","en":"How much time does it take?"},"answer":{"mk":"As much as you want to give. Most members spend 2–4 hours a week: the Wednesday meeting plus some team work. Before a big event it can be more, and that’s usually the fun part.","en":"As much as you want to give. Most members spend 2–4 hours a week: the Wednesday meeting plus some team work. Before a big event it can be more, and that’s usually the fun part."}},{"id":"faq-3","question":{"mk":"Does it cost anything?","en":"Does it cost anything?"},"answer":{"mk":"Applying and trying it out is free. Full members pay 600 MKD per academic year. International events usually have a small participation fee.","en":"Applying and trying it out is free. Full members pay 600 MKD per academic year. International events usually have a small participation fee."}},{"id":"faq-4","question":{"mk":"Do I need to speak English?","en":"Do I need to speak English?"},"answer":{"mk":"Basic English is enough to start. Local activities are in Macedonian; international events are in English and a great way to practise.","en":"Basic English is enough to start. Local activities are in Macedonian; international events are in English and a great way to practise."}},{"id":"faq-5","question":{"mk":"Can I join in my final year?","en":"Can I join in my final year?"},"answer":{"mk":"Yes. You can stay active until you graduate and then join our alumni.","en":"Yes. You can stay active until you graduate and then join our alumni."}},{"id":"faq-6","question":{"mk":"When can I apply?","en":"When can I apply?"},"answer":{"mk":"Membership applications open at the start of each semester. The form below shows whether they are open right now.","en":"Membership applications open at the start of each semester. The form below shows whether they are open right now."}}],"apply":{"open":true,"nextRound":{"mk":"February 2027","en":"February 2027"},"intro":{"mk":"Tell us a bit about yourself. We''ll reply within 3 days and invite you to the next weekly meeting.","en":"Tell us a bit about yourself. We''ll reply within 3 days and invite you to the next weekly meeting."},"faculties":[{"id":"fac-1","text":{"mk":"FEEIT","en":"FEEIT"}},{"id":"fac-2","text":{"mk":"FINKI","en":"FINKI"}},{"id":"fac-3","text":{"mk":"Faculty of Mechanical Engineering","en":"Faculty of Mechanical Engineering"}},{"id":"fac-4","text":{"mk":"Other faculty at UKIM","en":"Other faculty at UKIM"}},{"id":"fac-5","text":{"mk":"Other university","en":"Other university"}}],"interests":[{"id":"int-1","text":{"mk":"IT","en":"IT"}},{"id":"int-2","text":{"mk":"PR","en":"PR"}},{"id":"int-3","text":{"mk":"Design","en":"Design"}},{"id":"int-4","text":{"mk":"Events","en":"Events"}},{"id":"int-5","text":{"mk":"Fundraising","en":"Fundraising"}},{"id":"int-6","text":{"mk":"Trainings","en":"Trainings"}}],"heardFrom":[{"id":"heard-1","text":{"mk":"Instagram","en":"Instagram"}},{"id":"heard-2","text":{"mk":"A friend","en":"A friend"}},{"id":"heard-3","text":{"mk":"Info stand at FEEIT","en":"Info stand at FEEIT"}},{"id":"heard-4","text":{"mk":"Facebook","en":"Facebook"}},{"id":"heard-5","text":{"mk":"An event","en":"An event"}},{"id":"heard-6","text":{"mk":"Other","en":"Other"}}]}}'::jsonb, true);
insert into public.page_content (page, content, is_sample) values ('partners', '{"hero":{"eyebrow":{"mk":"For Companies","en":"For Companies"},"title":{"mk":"Meet the engineers of tomorrow","en":"Meet the engineers of tomorrow"},"lead":{"mk":"Partner with EESTEC LC Skopje to reach electrical engineering and computer science students at FEEIT and across Europe.","en":"Partner with EESTEC LC Skopje to reach electrical engineering and computer science students at FEEIT and across Europe."},"primaryLabel":{"mk":"Get in touch","en":"Get in touch"},"offerLabel":{"mk":"Partnership offer","en":"Partnership offer"}},"reach":{"title":{"mk":"Who you reach","en":"Who you reach"},"stats":[{"id":"reach-1","value":{"mk":"1,200+","en":"1,200+"},"label":{"mk":"students at our events each year","en":"students at our events each year"}},{"id":"reach-2","value":{"mk":"80","en":"80"},"label":{"mk":"active LC Skopje members","en":"active LC Skopje members"}},{"id":"reach-3","value":{"mk":"25+","en":"25+"},"label":{"mk":"local and international events a year","en":"local and international events a year"}},{"id":"reach-4","value":{"mk":"5,000+","en":"5,000+"},"label":{"mk":"students in the EESTEC network","en":"students in the EESTEC network"}}]},"why":{"eyebrow":{"mk":"Why partner with us","en":"Why partner with us"},"title":{"mk":"What your company gets","en":"What your company gets"},"cards":[{"id":"why-1","icon":"users","title":{"mk":"Reach EE & CS students","en":"Reach EE & CS students"},"text":{"mk":"Meet motivated students of electrical engineering and computer science before they graduate.","en":"Meet motivated students of electrical engineering and computer science before they graduate."}},{"id":"why-2","icon":"star","title":{"mk":"Employer branding","en":"Employer branding"},"text":{"mk":"Your logo and story at our events, on our website and on our social media.","en":"Your logo and story at our events, on our website and on our social media."}},{"id":"why-3","icon":"chip","title":{"mk":"Workshops","en":"Workshops"},"text":{"mk":"Run a hands-on workshop or tech talk on your own technology, for students who chose to be there.","en":"Run a hands-on workshop or tech talk on your own technology, for students who chose to be there."}},{"id":"why-4","icon":"briefcase","title":{"mk":"Career events","en":"Career events"},"text":{"mk":"A stand at our job fair and career day, plus job posts shared with our members.","en":"A stand at our job fair and career day, plus job posts shared with our members."}}]},"packages":{"eyebrow":{"mk":"Collaboration options","en":"Collaboration options"},"title":{"mk":"Ways to work together","en":"Ways to work together"},"note":{"mk":"Prices and full details are in the partnership offer. Every package can be adjusted to your goals.","en":"Prices and full details are in the partnership offer. Every package can be adjusted to your goals."},"badge":{"mk":"Most chosen","en":"Most chosen"},"items":[{"id":"package-partner","name":{"mk":"Partner","en":"Partner"},"text":{"mk":"A simple way to support students and get visibility.","en":"A simple way to support students and get visibility."},"priceText":{"mk":"","en":""},"items":[{"id":"package-partner-item-1","text":{"mk":"Logo on the website and at one event","en":"Logo on the website and at one event"}},{"id":"package-partner-item-2","text":{"mk":"Thank-you post on our social media","en":"Thank-you post on our social media"}},{"id":"package-partner-item-3","text":{"mk":"Invitation to our partner day","en":"Invitation to our partner day"}}],"highlighted":false,"cta":{"mk":"Ask about Partner","en":"Ask about Partner"}},{"id":"package-gold","name":{"mk":"Gold partner","en":"Gold partner"},"text":{"mk":"Regular contact with students through the year.","en":"Regular contact with students through the year."},"priceText":{"mk":"","en":""},"items":[{"id":"package-gold-item-1","text":{"mk":"Everything in Partner","en":"Everything in Partner"}},{"id":"package-gold-item-2","text":{"mk":"Bigger logo on the Home page","en":"Bigger logo on the Home page"}},{"id":"package-gold-item-3","text":{"mk":"One company workshop or tech talk a year","en":"One company workshop or tech talk a year"}},{"id":"package-gold-item-4","text":{"mk":"A stand at the job fair","en":"A stand at the job fair"}},{"id":"package-gold-item-5","text":{"mk":"Job posts shared with members","en":"Job posts shared with members"}}],"highlighted":true,"cta":{"mk":"Ask about Gold","en":"Ask about Gold"}},{"id":"package-main","name":{"mk":"Main partner","en":"Main partner"},"text":{"mk":"The strongest presence, including our international events.","en":"The strongest presence, including our international events."},"priceText":{"mk":"","en":""},"items":[{"id":"package-main-item-1","text":{"mk":"Everything in Gold","en":"Everything in Gold"}},{"id":"package-main-item-2","text":{"mk":"Largest logo, first on the Home page","en":"Largest logo, first on the Home page"}},{"id":"package-main-item-3","text":{"mk":"Branding at our international workshop","en":"Branding at our international workshop"}},{"id":"package-main-item-4","text":{"mk":"Two workshops a year and a company visit","en":"Two workshops a year and a company visit"}},{"id":"package-main-item-5","text":{"mk":"Access to CVs of members who opt in","en":"Access to CVs of members who opt in"}}],"highlighted":false,"cta":{"mk":"Ask about Main partner","en":"Ask about Main partner"}}],"singlesTitle":{"mk":"Or pick a single collaboration","en":"Or pick a single collaboration"},"singles":[{"id":"single-1","icon":"chip","title":{"mk":"Company workshop","en":"Company workshop"},"text":{"mk":"A half-day or full-day hands-on session.","en":"A half-day or full-day hands-on session."}},{"id":"single-2","icon":"mic","title":{"mk":"Tech talk","en":"Tech talk"},"text":{"mk":"A 45-minute talk at FEEIT with Q&A.","en":"A 45-minute talk at FEEIT with Q&A."}},{"id":"single-3","icon":"briefcase","title":{"mk":"Job fair stand","en":"Job fair stand"},"text":{"mk":"Meet students at our yearly job fair.","en":"Meet students at our yearly job fair."}},{"id":"single-4","icon":"flag","title":{"mk":"Event sponsorship","en":"Event sponsorship"},"text":{"mk":"Support one event and be seen there.","en":"Support one event and be seen there."}}]},"offer":{"mediaId":"143c9a27-1593-5946-aaff-e8c9a3a3bde4","title":{"mk":"Partnership offer 2026/27","en":"Partnership offer 2026/27"},"text":{"mk":"All packages, prices and last year’s results in one document.","en":"All packages, prices and last year’s results in one document."},"pages":{"mk":"14 pages","en":"14 pages"},"downloadLabel":{"mk":"Download PDF","en":"Download PDF"}},"partners":{"eyebrow":{"mk":"Our partners","en":"Our partners"},"title":{"mk":"Companies that already work with us","en":"Companies that already work with us"},"pastTitle":{"mk":"Past partners","en":"Past partners"}},"contact":{"eyebrow":{"mk":"Contact","en":"Contact"},"title":{"mk":"Let’s talk","en":"Let’s talk"},"text":{"mk":"Tell us what you have in mind. We’ll suggest the best format and send you the details.","en":"Tell us what you have in mind. We’ll suggest the best format and send you the details."},"person":{"name":"Ivana Kostova","role":{"mk":"Head of Fundraising, EESTEC LC Skopje","en":"Head of Fundraising, EESTEC LC Skopje"},"email":"partners@eestec.mk"}}}'::jsonb, true);
