insert into public.memories (id, author_id, author_deleted, slug, status, source, title, body, event_id, other_event_name, city, country, happened_on, cover_media_id, cover_sample, cover_alt, cover_credit, featured_on_home, rejection_reason, reviewed_by_name, reviewed_at, submitted_at, published_at, reads_count, created_at, updated_at, is_sample) values ('6357dbd0-d1ce-55e7-a03a-78b9c0334500', 'ba0b43de-7506-53b4-bebf-3cc91074d4b1', false, 'power-up-the-lab-day-i-did-not-expect', 'published', 'editor', 'Power Up: the lab day I did not expect', '<p>I signed up for Power Up because I wanted to understand why my grid-simulation homework never balanced. I did not expect the answer to involve a hard hat.</p><p>The lab day at FEEIT was the best of the week. We split into teams of four, each with a small model of a grid: one solar plant, one gas plant, a city that wakes up and goes to sleep. The task was simple to say and hard to do: keep the frequency steady through a cloudy afternoon.</p><p>My team failed twice. The third time a student from Lisbon suggested we stop chasing the sun and start planning for the clouds, and the numbers finally stayed flat. The jury, two engineers from a local energy company, asked us how we would explain the result to someone who has never opened a textbook. That question stayed with me longer than the answer.</p><p>If you are thinking about applying for the next one: you do not need to know anything about power systems. You need to be curious and willing to be wrong in front of strangers.</p>', '4c9b724d-d545-5920-9f8c-1ea5877b2954', '', 'Skopje', 'North Macedonia', '2026-05-20', null, 'The grid challenge: four students around a model of a power grid', 'Four students around a table-sized model of a power grid, one pointing at a gauge', 'Daniel Ristov', true, '', 'Ivana Kostova', '2026-06-02T10:00:00+02:00', null, '2026-06-02T10:00:00+02:00', 1240, '2026-06-02T10:00:00+02:00', '2026-06-02T10:00:00+02:00', true);
