insert into public.memory_photos (id, memory_id, media_id, sample_caption, alt, caption, sort_order, is_sample) values ('6c371aba-4d68-5674-9ff7-19b93eea3620', '6357dbd0-d1ce-55e7-a03a-78b9c0334500', null, 'Group photo', 'All participants in front of the faculty building', '', 6, true);
insert into public.memories (id, author_id, author_deleted, slug, status, source, title, body, event_id, other_event_name, city, country, happened_on, cover_media_id, cover_sample, cover_alt, cover_credit, featured_on_home, rejection_reason, reviewed_by_name, reviewed_at, submitted_at, published_at, reads_count, created_at, updated_at, is_sample) values ('b121432b-df7a-5bbf-ac56-383f00c75006', '8000ffa0-1071-5081-a86b-9d753766fb65', false, 'five-days-in-delft-zero-days-of-sun', 'published', 'editor', 'Five days in Delft, zero days of sun', '<p>The plan for the exchange said five days, three workshops and a bike for everyone. It said nothing about the weather, and I learned why on the first morning.</p><p>Delft is small enough to cross in twenty minutes and wet enough to make every one of them an adventure. The local committee had a rule: if you are late because of the rain, you buy the coffee. By Wednesday I owed eleven coffees.</p><p>We visited a lab that builds sensors for wind turbines, spent an evening in a student house arguing about the right way to make stroopwafels, and cycled to the sea on the last day. It rained the whole way. Nobody complained.</p>', '8831261d-21f9-566c-ad86-88276ab2d5b5', '', 'Delft', 'Netherlands', '2026-04-16', null, 'A row of bikes in the rain on a Delft canal', 'Bikes parked along a canal in the rain', 'Marija Stojanovska', false, '', 'Ivana Kostova', '2026-05-02T09:00:00+02:00', null, '2026-05-02T09:00:00+02:00', 318, '2026-05-02T09:00:00+02:00', '2026-05-02T09:00:00+02:00', true);
insert into public.memory_photos (id, memory_id, media_id, sample_caption, alt, caption, sort_order, is_sample) values ('3cf58fbf-8a83-50c9-b7c8-44bee84fca94', 'b121432b-df7a-5bbf-ac56-383f00c75006', null, 'Canal in the rain', 'A canal with bikes and wet cobblestones', 'Canal in the rain', 0, true);
insert into public.memory_photos (id, memory_id, media_id, sample_caption, alt, caption, sort_order, is_sample) values ('ff676291-79ae-521f-8273-9cb77d8e3af9', 'b121432b-df7a-5bbf-ac56-383f00c75006', null, 'The wind turbine lab', 'Students in front of a test rig for wind turbine sensors', '', 1, true);
insert into public.memory_photos (id, memory_id, media_id, sample_caption, alt, caption, sort_order, is_sample) values ('100b2c74-ecb1-5a65-9a96-93dc2d138d8f', 'b121432b-df7a-5bbf-ac56-383f00c75006', null, 'Stroopwafel debate', 'A kitchen table covered in waffles and cups', '', 2, true);
insert into public.memory_photos (id, memory_id, media_id, sample_caption, alt, caption, sort_order, is_sample) values ('c714bde6-cf92-508b-9d71-cb749b08871e', 'b121432b-df7a-5bbf-ac56-383f00c75006', null, 'The ride to the sea', 'A line of cyclists on a dyke under a grey sky', '', 3, true);
insert into public.memory_revisions (id, memory_id, status, content, reason, reviewed_by_name, reviewed_at, submitted_at, is_sample) values ('d0ffda08-5885-5606-a459-09dbc1c48d30', 'b121432b-df7a-5bbf-ac56-383f00c75006', 'pending', '{"eventId":"8831261d-21f9-566c-ad86-88276ab2d5b5","otherEventName":"","happenedOn":"2026-04-16","body":"<p>The plan for the exchange said five days, three workshops and a bike for everyone. It said nothing about the weather, and I learned why on the first morning.</p><p>Delft is small enough to cross in twenty minutes and wet enough to make every one of them an adventure. The local committee had a rule: if you are late because of the rain, you buy the coffee. By Wednesday I owed eleven coffees.</p><p>We visited a lab that builds sensors for wind turbines, spent an evening in a student house arguing about the right way to make stroopwafels, and cycled to the sea on the last day. It rained the whole way. Nobody complained.</p><p>A note for anyone going next year: pack a second pair of shoes. The local committee will lend you everything else.</p>","cover":{"fileId":null,"sample":"A row of bikes in the rain on a Delft canal","alt":"Bikes parked along a canal in the rain","credit":"Marija Stojanovska"},"title":"Five days in Delft, zero days of sun","city":"Delft","country":"Netherlands"}'::jsonb, '', '', null, '2026-10-03T16:20:00+02:00', true);
