insert into public.memory_revision_photos (id, revision_id, media_id, sample_caption, alt, caption, sort_order, is_sample) values ('a1e9ed7e-5f77-5cad-ada2-8d4ec7cd22a8', 'd0ffda08-5885-5606-a459-09dbc1c48d30', null, 'Stroopwafel debate', 'A kitchen table covered in waffles and cups', '', 2, true);
insert into public.memory_revision_photos (id, revision_id, media_id, sample_caption, alt, caption, sort_order, is_sample) values ('3a6c6379-8a6b-5d17-8810-4b72d879aa6f', 'd0ffda08-5885-5606-a459-09dbc1c48d30', null, 'The ride to the sea', 'A line of cyclists on a dyke under a grey sky', '', 3, true);
insert into public.memories (id, author_id, author_deleted, slug, status, source, title, body, event_id, other_event_name, city, country, happened_on, cover_media_id, cover_sample, cover_alt, cover_credit, featured_on_home, rejection_reason, reviewed_by_name, reviewed_at, submitted_at, published_at, reads_count, created_at, updated_at, is_sample) values ('017bb347-479f-5cdf-8036-2bf404a91da5', '6968c77b-9f73-5c37-9d27-2a78798ce64f', false, 'what-24-students-taught-me-about-the-power-grid', 'published', 'editor', 'What 24 students taught me about the power grid', '<p>Before Power Up I thought a power grid was wires. After it I think a grid is a conversation that never stops: producers and consumers agreeing, every second, on how much is enough.</p><p>The lecture that changed my mind was given by an engineer who works in a control room. She showed a recording of the evening a large plant went offline and the frequency dropped in a few seconds. The room was silent. Then she showed how the other plants answered, one after another, and the line came back up.</p><p>I left the lecture wanting to work on something that matters to everyone and that nobody notices until it breaks.</p>', '4c9b724d-d545-5920-9f8c-1ea5877b2954', '', 'Skopje', 'North Macedonia', '2026-05-21', null, 'The lecture hall during the control-room talk', 'A full lecture hall watching a graph of the grid frequency', 'Ana Trajkovska', false, '', 'Ivana Kostova', '2026-06-09T12:00:00+02:00', null, '2026-06-09T12:00:00+02:00', 402, '2026-06-09T12:00:00+02:00', '2026-06-09T12:00:00+02:00', true);
insert into public.memory_photos (id, memory_id, media_id, sample_caption, alt, caption, sort_order, is_sample) values ('6195f2f9-2b32-5578-a6c0-9f564c857512', '017bb347-479f-5cdf-8036-2bf404a91da5', null, 'The control-room talk', 'A speaker pointing at a graph on a large screen', 'The control-room talk', 0, true);
insert into public.memory_photos (id, memory_id, media_id, sample_caption, alt, caption, sort_order, is_sample) values ('c7ec86f0-095d-5e53-8d2a-fabd230b711c', '017bb347-479f-5cdf-8036-2bf404a91da5', null, 'Questions after the lecture', 'Students lining up at a microphone', '', 1, true);
insert into public.memories (id, author_id, author_deleted, slug, status, source, title, body, event_id, other_event_name, city, country, happened_on, cover_media_id, cover_sample, cover_alt, cover_credit, featured_on_home, rejection_reason, reviewed_by_name, reviewed_at, submitted_at, published_at, reads_count, created_at, updated_at, is_sample) values ('07494c1c-b390-5cfe-82aa-28b19ef0045c', 'e27e5cbf-93c4-5b76-86fe-465f6e552043', false, 'why-i-keep-coming-back-to-eestech', 'published', 'editor', 'Why I keep coming back to EESTech', '<p>The EESTech Challenge local round is the one event of the year where I am happy to be nervous. Eight teams, six hours, one problem that nobody has seen before.</p><p>This year the problem was about sorting parcels with as few robots as possible. We built our solution on a whiteboard, threw it away at lunch and rebuilt it in the last hour. We came third and I have never been prouder of a third place.</p><p>What I like most is that the jury stays to talk afterwards. They are not looking for the right answer, they are looking for people who can explain why they chose the one they did.</p>', 'b6de1b9e-dcd9-5c1c-8ca9-828e7cb68995', '', 'Skopje', 'North Macedonia', '2026-03-14', null, 'Eight teams at long tables, laptops open', 'Teams working at long tables with laptops and whiteboards', 'Ivana Kostova', false, '', 'Ivana Kostova', '2026-03-24T18:00:00+01:00', null, '2026-03-24T18:00:00+01:00', 211, '2026-03-24T18:00:00+01:00', '2026-03-24T18:00:00+01:00', true);
insert into public.memory_photos (id, memory_id, media_id, sample_caption, alt, caption, sort_order, is_sample) values ('00e67474-8009-5e18-bb68-b3085f59b987', '07494c1c-b390-5cfe-82aa-28b19ef0045c', null, 'Whiteboard, first version', 'A whiteboard covered in boxes and arrows', 'Whiteboard, first version', 0, true);
insert into public.memory_photos (id, memory_id, media_id, sample_caption, alt, caption, sort_order, is_sample) values ('c6271d95-a376-59d6-9410-4e1587096b05', '07494c1c-b390-5cfe-82aa-28b19ef0045c', null, 'The jury listens', 'Three jury members listening to a student presentation', '', 1, true);
insert into public.memory_photos (id, memory_id, media_id, sample_caption, alt, caption, sort_order, is_sample) values ('fbfdaf57-7493-5432-8670-e93ae8b95742', '07494c1c-b390-5cfe-82aa-28b19ef0045c', null, 'The third place', 'A team holding a certificate and laughing', '', 2, true);
insert into public.memories (id, author_id, author_deleted, slug, status, source, title, body, event_id, other_event_name, city, country, happened_on, cover_media_id, cover_sample, cover_alt, cover_credit, featured_on_home, rejection_reason, reviewed_by_name, reviewed_at, submitted_at, published_at, reads_count, created_at, updated_at, is_sample) values ('8aabaf07-5709-5ad3-9419-4d319bf727d2', 'ba0b43de-7506-53b4-bebf-3cc91074d4b1', false, 'a-week-in-tallinn-and-a-very-good-sauna', 'published', 'editor', 'A week in Tallinn and a very good sauna', '<p>I went to Tallinn in February because it was the only city with a free bed and an open EESTEC committee. I came home with a new favourite sauna and three friends I still write to every week.</p><p>The local committee organised a walk through the old town, a visit to a startup that makes tiny satellites, and a night of board games that ended with a very serious argument about the rules of a game nobody had finished.</p><p>If you ever have the chance to visit another local committee, go. The best part is not the sights. It is being welcomed by people who owe you nothing.</p>', null, 'Visit to LC Tallinn', 'Tallinn', 'Estonia', '2026-02-12', null, 'Old town rooftops covered in snow', 'Snow-covered rooftops of Tallinn old town at dusk', 'Daniel Ristov', false, '', 'Ivana Kostova', '2026-02-26T11:00:00+01:00', null, '2026-02-26T11:00:00+01:00', 164, '2026-02-26T11:00:00+01:00', '2026-02-26T11:00:00+01:00', true);
insert into public.memory_photos (id, memory_id, media_id, sample_caption, alt, caption, sort_order, is_sample) values ('31370e5e-8118-55b9-a69d-e45dcbe33891', '8aabaf07-5709-5ad3-9419-4d319bf727d2', null, 'The old town walk', 'A group walking through a narrow snowy street', 'The old town walk', 0, true);
insert into public.memory_photos (id, memory_id, media_id, sample_caption, alt, caption, sort_order, is_sample) values ('8a0b3cbd-ce60-5695-92ba-9fde8daed986', '8aabaf07-5709-5ad3-9419-4d319bf727d2', null, 'The satellite startup', 'A table with a tiny satellite and a ruler next to it', '', 1, true);
insert into public.memory_photos (id, memory_id, media_id, sample_caption, alt, caption, sort_order, is_sample) values ('af352831-8b7e-554b-93e5-73e56e71fd78', '8aabaf07-5709-5ad3-9419-4d319bf727d2', null, 'Board game night', 'Six people around a board game with a pile of cards', '', 2, true);
insert into public.memories (id, author_id, author_deleted, slug, status, source, title, body, event_id, other_event_name, city, country, happened_on, cover_media_id, cover_sample, cover_alt, cover_credit, featured_on_home, rejection_reason, reviewed_by_name, reviewed_at, submitted_at, published_at, reads_count, created_at, updated_at, is_sample) values ('6a89ba60-21a9-50d7-9de1-aaf3425b2817', '6968c77b-9f73-5c37-9d27-2a78798ce64f', false, 'my-first-pcb-and-the-chip-that-went-quiet', 'published', 'editor', 'My first PCB, and the chip that went quiet', '<p>My first printed circuit board took two evenings to draw and eleven seconds to ruin. I connected the power to the wrong pin and a very small chip went quiet for good.</p><p>The KiCad workshop did not make me good at it. It made me unafraid of it. By the end of the second day I had a board that blinked, and a list of mistakes I will never make again, which is more than I can say for most of my homework.</p>', 'c3c3a942-ee25-51c4-a0a5-61af9fd2d098', '', 'Skopje', 'North Macedonia', '2026-02-27', null, 'A small blinking circuit board on a desk', 'A small circuit board with a blinking LED on a desk', 'Ana Trajkovska', false, '', 'Ivana Kostova', '2026-03-05T14:00:00+01:00', null, '2026-03-05T14:00:00+01:00', 97, '2026-03-05T14:00:00+01:00', '2026-03-05T14:00:00+01:00', true);
insert into public.memory_photos (id, memory_id, media_id, sample_caption, alt, caption, sort_order, is_sample) values ('33feae32-67ea-5c27-80a3-40320d35f608', '6a89ba60-21a9-50d7-9de1-aaf3425b2817', null, 'The board that blinked', 'A circuit board with one LED lit', 'The board that blinked', 0, true);
insert into public.memories (id, author_id, author_deleted, slug, status, source, title, body, event_id, other_event_name, city, country, happened_on, cover_media_id, cover_sample, cover_alt, cover_credit, featured_on_home, rejection_reason, reviewed_by_name, reviewed_at, submitted_at, published_at, reads_count, created_at, updated_at, is_sample) values ('b246d363-a5b6-5bc6-aaa3-57d0c4c9a900', '92415856-7264-5467-a08a-438e8b79ad21', false, 'robomac-2025-from-the-side-nobody-sees', 'published', 'editor', 'RoboMac 2025, from the side nobody sees', '<p>RoboMac 2025 had 26 teams, one very long line for the soldering irons and the loudest cheering I have heard in a lecture hall.</p><p>I was in the organising team, which meant I saw the competition from the side nobody sees: the one where you carry tables at seven in the morning and hide a spare battery in your backpack just in case. It was worth every table.</p>', '8ae67014-d101-5efd-9e68-cb2e44e9895b', '', 'Skopje', 'North Macedonia', '2025-04-12', null, 'Teams soldering in a crowded lecture hall', 'Students soldering robot parts at crowded tables', 'Stefan Nikolovski', false, '', 'Ivana Kostova', '2025-05-12T09:00:00+02:00', null, '2025-05-12T09:00:00+02:00', 188, '2025-05-12T09:00:00+02:00', '2025-05-12T09:00:00+02:00', true);
