insert into public.memory_photos (id, memory_id, media_id, sample_caption, alt, caption, sort_order, is_sample) values ('d1c847bc-c211-5f69-98ee-337e48d01285', 'b246d363-a5b6-5bc6-aaa3-57d0c4c9a900', null, 'The final round', 'Two small robots facing each other in an arena', '', 1, true);
insert into public.memories (id, author_id, author_deleted, slug, status, source, title, body, event_id, other_event_name, city, country, happened_on, cover_media_id, cover_sample, cover_alt, cover_credit, featured_on_home, rejection_reason, reviewed_by_name, reviewed_at, submitted_at, published_at, reads_count, created_at, updated_at, is_sample) values ('f0112471-9a48-53fb-8854-a509a844032e', null, true, 'a-night-train-and-a-bakery-in-prague', 'published', 'editor', 'A night train and a bakery in Prague', '<p>The night train from Vienna was supposed to arrive at six. It arrived at nine, which is why I saw the whole of Prague at breakfast time with a rucksack and no plan.</p><p>The local committee took us to a bridge, a bakery and a roof where the whole city turned gold. I still think about the bakery.</p>', null, 'Visit to LC Praha', 'Prague', 'Czechia', '2025-08-22', null, 'A bridge at sunrise', 'A stone bridge over a river at sunrise', '', false, '', 'Ivana Kostova', '2025-09-03T10:00:00+02:00', null, '2025-09-03T10:00:00+02:00', 76, '2025-09-03T10:00:00+02:00', '2025-09-03T10:00:00+02:00', true);
insert into public.memory_photos (id, memory_id, media_id, sample_caption, alt, caption, sort_order, is_sample) values ('eb124835-eab3-52b2-abd9-53561f162c13', 'f0112471-9a48-53fb-8854-a509a844032e', null, 'The bakery', 'A bakery window full of pastries', 'The bakery', 0, true);
insert into public.memories (id, author_id, author_deleted, slug, status, source, title, body, event_id, other_event_name, city, country, happened_on, cover_media_id, cover_sample, cover_alt, cover_credit, featured_on_home, rejection_reason, reviewed_by_name, reviewed_at, submitted_at, published_at, reads_count, created_at, updated_at, is_sample) values ('74847afb-7772-5e83-ae20-61e133d55617', '8000ffa0-1071-5081-a86b-9d753766fb65', false, 'seven-days-28-nationalities-and-one-very-long-bus-ride-to-ohrid', 'pending', 'editor', 'Seven days, 28 nationalities and one very long bus ride to Ohrid', '<p>Seven days, 28 nationalities and one very long bus ride to Ohrid. Here is what I will remember from Power Up, written down before I forget it.</p><p>The first morning, at the FEEIT entrance, nobody knew anybody. By the third, we had a group chat with 28 flags in its name and a rule that nobody eats alone. The week had lectures and labs and a day at a solar plant, but the thing I will remember is the clapping game on the bus.</p><p>Thank you to the 16 organisers who made it look easy. I know how much work it was.</p><p>There is a point on every international event where the group stops being 28 strangers. For us it was somewhere on the road to Ohrid, on a bus with a broken air conditioner and a driver who knew every song.</p><p>We left Skopje at nine. By ten the Spanish group had taught the whole bus a clapping game, by eleven the Poles had answered with a song, and by noon we had stopped at a roadside stand and bought far too many peaches.</p><p>The rest of the weekend, the old town, the lake, the international night where everyone brought something from home, was wonderful. But when I think about Power Up, I think about that bus.</p>', '4c9b724d-d545-5920-9f8c-1ea5877b2954', '', 'Ohrid', 'North Macedonia', '2026-05-24', null, 'The group on the lakeside in Ohrid', 'Twenty-eight students standing in a row on the lakeside promenade', 'Marija Stojanovska', false, '', '', null, '2026-10-02T09:12:00+02:00', null, 0, '2026-10-02T09:00:00+02:00', '2026-10-02T09:12:00+02:00', true);
