insert into public.memory_photos (id, memory_id, media_id, sample_caption, alt, caption, sort_order, is_sample) values ('6fee47ea-350b-5360-ba56-644656e4b5ca', '74847afb-7772-5e83-ae20-61e133d55617', null, 'The ride home', 'Students asleep on the bus with a pile of backpacks', '', 5, true);
insert into public.memories (id, author_id, author_deleted, slug, status, source, title, body, event_id, other_event_name, city, country, happened_on, cover_media_id, cover_sample, cover_alt, cover_credit, featured_on_home, rejection_reason, reviewed_by_name, reviewed_at, submitted_at, published_at, reads_count, created_at, updated_at, is_sample) values ('d160a090-bd63-5fef-bcad-db1e072e3153', '6968c77b-9f73-5c37-9d27-2a78798ce64f', false, 'two-days-of-embedded-rust-and-one-borrow-checker', 'pending', 'editor', 'Two days of embedded Rust and one borrow checker', '<p>The workshop promised that Rust would stop me from making mistakes on a microcontroller. What it did first was stop me from compiling anything at all.</p><p>By the second afternoon the borrow checker and I had come to an understanding, and the board on my desk blinked in the pattern I had written.</p>', 'c81002cb-9b0e-568b-9dec-764565798c34', '', 'Skopje', 'North Macedonia', '2025-11-08', null, 'A development board connected to a laptop', 'A small development board with a cable running to a laptop', 'Ana Trajkovska', false, '', '', null, '2026-10-03T08:30:00+02:00', null, 0, '2026-10-03T08:00:00+02:00', '2026-10-03T08:30:00+02:00', true);
insert into public.memory_photos (id, memory_id, media_id, sample_caption, alt, caption, sort_order, is_sample) values ('d3075252-662c-5c10-899d-34e0af3d814b', 'd160a090-bd63-5fef-bcad-db1e072e3153', null, 'The first blink', 'A development board with a green LED on', 'The first blink', 0, true);
insert into public.memories (id, author_id, author_deleted, slug, status, source, title, body, event_id, other_event_name, city, country, happened_on, cover_media_id, cover_sample, cover_alt, cover_credit, featured_on_home, rejection_reason, reviewed_by_name, reviewed_at, submitted_at, published_at, reads_count, created_at, updated_at, is_sample) values ('354483d7-9d50-5b73-975a-f7cef6b7220d', '92415856-7264-5467-a08a-438e8b79ad21', false, 'robomac-2026-a-fan-of-the-small-robots', 'pending', 'editor', 'RoboMac 2026: a fan of the small robots', '<p>There is a robot at RoboMac that is smaller than a matchbox and has won two years in a row. I went to find out why.</p><p>The team behind it told me the secret: it is not the motors, it is the patience to tune the sensors until the very last minute.</p>', '1d54d6fd-7a89-55f2-89db-88a1b6a308db', '', 'Skopje', 'North Macedonia', '2026-04-11', null, 'A tiny robot on a black arena line', 'A very small robot on a black line in a white arena', 'Stefan Nikolovski', false, '', '', null, '2026-10-04T08:25:00+02:00', null, 0, '2026-10-04T08:00:00+02:00', '2026-10-04T08:25:00+02:00', true);
insert into public.memories (id, author_id, author_deleted, slug, status, source, title, body, event_id, other_event_name, city, country, happened_on, cover_media_id, cover_sample, cover_alt, cover_credit, featured_on_home, rejection_reason, reviewed_by_name, reviewed_at, submitted_at, published_at, reads_count, created_at, updated_at, is_sample) values ('82033e02-7ebb-5b09-afc7-7b21bc3b057c', '8000ffa0-1071-5081-a86b-9d753766fb65', false, null, 'draft', 'editor', 'Notes from the RoboMac jury table', '<p>I sat at the jury table for the first time this year. Here is what I wrote down while the robots ran.</p>', '1d54d6fd-7a89-55f2-89db-88a1b6a308db', '', 'Skopje', 'North Macedonia', null, null, null, null, null, false, '', '', null, null, null, 0, '2026-10-05T19:00:00+02:00', '2026-10-07T18:42:00+02:00', true);
insert into public.memories (id, author_id, author_deleted, slug, status, source, title, body, event_id, other_event_name, city, country, happened_on, cover_media_id, cover_sample, cover_alt, cover_credit, featured_on_home, rejection_reason, reviewed_by_name, reviewed_at, submitted_at, published_at, reads_count, created_at, updated_at, is_sample) values ('ea9c4139-6e6f-5c07-8fb2-766fc3b391f2', '8000ffa0-1071-5081-a86b-9d753766fb65', false, 'krakow-in-the-snow-part-two', 'rejected', 'editor', 'Kraków in the snow, part two', '<p>Krakow in winter looks like a postcard somebody forgot to colour in. We walked from the market square to the river in minus eight, ate soup in a milk bar and came back to the hostel with frozen fingers and a very good mood.</p><p>This was my second time in Krakow with EESTEC, and the first time with a camera that worked in the cold.</p>', null, 'Krakow Winter Exchange (visit)', 'Kraków', 'Poland', '2026-01-18', null, 'The market square under snow', '', '', false, 'Lovely story. Please add a description to each photo and a cover photo that shows people, not only snow. Then send it again and we will publish it.', 'Ivana Kostova', '2026-10-01T10:00:00+02:00', '2026-09-28T20:10:00+02:00', null, 0, '2026-09-20T12:00:00+02:00', '2026-10-01T10:00:00+02:00', true);
insert into public.memory_photos (id, memory_id, media_id, sample_caption, alt, caption, sort_order, is_sample) values ('2cdf3802-9362-5f94-a1e7-1aaabb770280', 'ea9c4139-6e6f-5c07-8fb2-766fc3b391f2', null, 'Milk bar soup', '', 'Milk bar soup', 0, true);
insert into public.memory_photos (id, memory_id, media_id, sample_caption, alt, caption, sort_order, is_sample) values ('513363ab-0f45-5be1-adf5-f98d53b936b7', 'ea9c4139-6e6f-5c07-8fb2-766fc3b391f2', null, 'The river at minus eight', '', '', 1, true);
insert into public.ideas (id, reference, type_id, title, description, name, email, user_id, is_anonymous, consent_at, locale, status, owner_id, owner_name, event_draft_id, created_at, is_sample) values ('8a11d053-c700-5663-8fe1-1b25a53fdd1f', 'IDE-2026-0001', 'c6dfb32e-f532-5556-b6dd-8b0b5e8cb57d', 'A beginner workshop on PCB design', 'Many first-years want to build hardware but have never designed a board. A two-evening workshop with KiCad, ending with a real PCB we order together, would be perfect before the EESTech Challenge.', 'Bojan Ilievski', 'bojan.i@example.org', null, false, '2026-10-04T11:20:00+02:00', 'en', 'under_review', '6968c77b-9f73-5c37-9d27-2a78798ce64f', 'Ana Trajkovska', null, '2026-10-04T11:20:00+02:00', true);
