insert into public.ideas (id, reference, type_id, title, description, name, email, user_id, is_anonymous, consent_at, locale, status, owner_id, owner_name, event_draft_id, created_at, is_sample) values ('f9fd76ca-ac29-5639-b830-81f5646ece2a', 'IDE-2026-0002', '39f8eb91-b797-520a-946b-626c8e603da6', 'Hackathon with the Faculty of Design', 'A weekend where electronics students build a prototype together with design students: one team, one product, a demo on Sunday. The faculties are a ten-minute walk apart.', null, null, null, true, null, 'en', 'new', null, null, null, '2026-10-04T09:02:00+02:00', true);
insert into public.ideas (id, reference, type_id, title, description, name, email, user_id, is_anonymous, consent_at, locale, status, owner_id, owner_name, event_draft_id, created_at, is_sample) values ('c9c5cbc9-b6eb-5cc8-95d6-f9d584548fc1', 'IDE-2026-0003', '200b1c5e-fa80-5329-be2d-e7703ff69a62', 'Dark mode for eestec.mk', 'I read the events page late in the evening, and the white background is hard on the eyes. A dark theme that follows the phone setting would be great.', 'Filip Angelovski', 'filip.a@example.org', '271bd088-1567-5b9e-a693-6bf930356b79', false, '2026-10-03T21:40:00+02:00', 'en', 'new', null, null, null, '2026-10-03T21:40:00+02:00', true);
insert into public.ideas (id, reference, type_id, title, description, name, email, user_id, is_anonymous, consent_at, locale, status, owner_id, owner_name, event_draft_id, created_at, is_sample) values ('65826e44-d466-527f-9cdf-c7d5a1564215', 'IDE-2026-0004', '18c47847-077f-520b-ace3-a33a13b92bda', 'Invite Gridnova for a lab tour', 'Gridnova builds smart-meter hardware in Skopje. A visit to their lab would fit the Power & energy topic and could lead to a partnership for internships.', null, null, null, true, null, 'en', 'new', null, null, null, '2026-10-03T14:05:00+02:00', true);
insert into public.ideas (id, reference, type_id, title, description, name, email, user_id, is_anonymous, consent_at, locale, status, owner_id, owner_name, event_draft_id, created_at, is_sample) values ('7597a3f4-040e-5604-9516-c5031d54bb7f', 'IDE-2026-0005', '6073dbdb-1043-5995-9b9c-29cfdae1ad8b', 'Study group before exam session', 'Two weeks before the January session we could book a room on Wednesday evenings for a study group: mixed years, mixed subjects, someone brings snacks.', 'Sara Dimova', 'sara.d@example.org', null, false, '2026-10-02T16:30:00+02:00', 'en', 'new', null, null, null, '2026-10-02T16:30:00+02:00', true);
insert into public.ideas (id, reference, type_id, title, description, name, email, user_id, is_anonymous, consent_at, locale, status, owner_id, owner_name, event_draft_id, created_at, is_sample) values ('a5cd9a5c-594c-55b2-b907-47afa7067463', 'IDE-2026-0006', 'c6dfb32e-f532-5556-b6dd-8b0b5e8cb57d', 'Soft skills training in Macedonian', 'Most soft-skills trainings are in English. A session in Macedonian about giving feedback and running meetings would reach students who are shy about English.', 'Ivana M.', 'ivana.m@example.org', null, false, '2026-10-01T12:10:00+02:00', 'mk', 'new', null, null, null, '2026-10-01T12:10:00+02:00', true);
insert into public.ideas (id, reference, type_id, title, description, name, email, user_id, is_anonymous, consent_at, locale, status, owner_id, owner_name, event_draft_id, created_at, is_sample) values ('23e2386e-72d2-5446-b706-0c16a0b18a8a', 'IDE-2026-0007', '39f8eb91-b797-520a-946b-626c8e603da6', 'Robotics workshop for high-schoolers', 'Invite the final-year classes of two local high schools for a Saturday of line-follower robots built by our members. It could bring in next year’s first-years.', 'Nikola J.', 'nikola.j@example.org', null, false, '2026-09-20T10:00:00+02:00', 'en', 'accepted', '6968c77b-9f73-5c37-9d27-2a78798ce64f', 'Ana Trajkovska', '1d54d6fd-7a89-55f2-89db-88a1b6a308db', '2026-09-20T10:00:00+02:00', true);
insert into public.ideas (id, reference, type_id, title, description, name, email, user_id, is_anonymous, consent_at, locale, status, owner_id, owner_name, event_draft_id, created_at, is_sample) values ('262c1909-0825-5791-8b59-f78e7a22350c', 'IDE-2026-0008', '200b1c5e-fa80-5329-be2d-e7703ff69a62', 'More photos on the Home page', 'The Home page could show a photo of the weekly meeting. It would make it less scary to come the first time.', null, null, null, true, null, 'en', 'archived', null, null, null, '2026-09-02T18:45:00+02:00', true);
insert into public.ideas (id, reference, type_id, title, description, name, email, user_id, is_anonymous, consent_at, locale, status, owner_id, owner_name, event_draft_id, created_at, is_sample) values ('b0809924-9649-5b3d-9dff-05cb2d90fbfd', 'IDE-2026-0009', '18c47847-077f-520b-ace3-a33a13b92bda', 'A career day with the companies from the Partners page', 'Several partners have open internships. One afternoon with a stand for each company, and a short talk about what they look for in a first CV, would help everyone.', 'A partner company', 'hr@example.org', null, false, '2026-08-28T09:15:00+02:00', 'en', 'accepted', '6968c77b-9f73-5c37-9d27-2a78798ce64f', 'Ana Trajkovska', null, '2026-08-28T09:15:00+02:00', true);
insert into public.ideas (id, reference, type_id, title, description, name, email, user_id, is_anonymous, consent_at, locale, status, owner_id, owner_name, event_draft_id, created_at, is_sample) values ('b7d6cd18-e0d6-583e-9e21-70c7b0461479', 'IDE-2026-0010', '39f8eb91-b797-520a-946b-626c8e603da6', 'Board game night after the weekly meeting', 'Once a month, stay after the Wednesday meeting for a board game night. A good way for new members to meet the older ones without a formal event.', 'Teodora Mitreva', 'teodora.m@example.org', null, false, '2026-09-15T19:00:00+02:00', 'en', 'under_review', null, null, null, '2026-09-15T19:00:00+02:00', true);
